import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker, workerOptions } from "./mocks/browser";


// const rooter = ReactDOM.createRoot(document.getElementById("root"));
// rooter.render(
//   <React.StrictMode>
//     <App />
//   </React.StrictMode>
// );

async function bootstrap() {
  // 깃허브 페이지 데모 : MSW 로 시작
  await worker.start(workerOptions);
  const rooter = ReactDOM.createRoot(document.getElementById("root"));
  rooter.render (
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}
bootstrap();
